{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '지쳤다고 말하면 핑계 같다'는 자동적 반응의 기원을 묻고 있으며, 이는 '나를 앞세우는 것은 이기적인 일이다'라는 핵심 신념의 뿌리를 탐색하는 질문이다. 아동기 배경에서 동생을 돌볼 때만 칭찬받고 자기 것을 요구하면 '이기적이다'라는 핀잔을 받은 경험이 이 신념의 원천이다."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data", "/situations/1"],
      "relevance": "내담자가 '지쳤다고 말하면 핑계 같다'고 한 것은 '내 필요나 힘듦을 앞세우는 것은 이기적이고 부끄러운 일이다'라는 태도의 직접적 표현이다. 상황 사례 1에서 '왜 아무도 나한테는 힘드냐고 안 물어보지'라는 생각이 든 뒤 '이런 생각 자체가 못됐어'로 차단하는 패턴과 동일하다."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/0"],
      "relevance": "'힘들어도 내색하지 않아야 한다'는 규칙이 내담자가 몸살 기운에도 주말 근무를 수락하고 집에 와서는 아프다는 말을 하지 않은 행동으로 나타난다. 상담사가 '자동이라는 말씀'이라 표현한 것이 이 규칙의 자동적 작동이다."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 '그건 제가 당연히 해야 하는 거고, 그거 말고도 딱히 뭐...'라며 자기 상태를 숨기는 방식이 이 대처 전략과 일치한다. 상황 사례 1에서 어머니가 간병을 당연하게 맡길 때 '네, 제가 할게요'라고 바로 답하고 화제를 돌리는 패턴과 같다."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": ["/situations/1"],
      "relevance": "쌓인 피로가 아이에게 폭발로 터진 뒤 '제가 못한 거잖아요'라며 심한 죄책감을 느끼는 것이 이 전략의 순환 구조(폭발→죄책감→더 헌신)와 정확히 일치한다. 상황 사례 1의 서운함을 배우자에게 '피곤해서 그래'로 덮는 패턴도 같은 맥락이다."
    }
  ]
}

